   656→            this.gameState.faUsed[pid] = false;
   657→        }
   658→
   659→        // 根据 drawInfo 计算抓牌起始位置
   660→        const drawInfo = this.gameState.drawInfo;
   661→        if (drawInfo && drawInfo.drawDirection) {
   662→            // 座位与方位映射
   663→            const seatToDirection = { 1: '东', 2: '南', 3: '西', 4: '北' };
   664→            // 方位到数组偏移的映射（牌墙按 东17墩 南17墩 西17墩 北17墩 排列，逆时针沿牌桌）
   665→            const directionToOffset = { 1: 0, 2: 17, 3: 34, 4: 51 };
   666→            // 抓牌方向从1往17，第1墩对应偏移0，第17墩对应偏移16
   667→            // drawPile 是起始墩号（1, 2, ..., 17）
   668→            const pileOffset = drawInfo.drawPile - 1; // 第1墩偏移0，第17墩偏移16
   669→            let startIndex = (directionToOffset[drawInfo.drawDirection] + pileOffset) * 2;
   670→            // 确保索引在有效范围内
   671→            startIndex = Math.max(0, Math.min(startIndex, this.gameState.deck.length - 1));
   672→
   673→            // 重排牌堆，使抓牌位置成为新的牌顶
   674→            if (startIndex > 0) {
   675→                const before = this.gameState.deck.slice(0, startIndex);
   676→                const after = this.gameState.deck.slice(startIndex);
   677→                this.gameState.deck = [...after, ...before];
   678→                console.log(`牌堆重排：从${seatToDirection[drawInfo.drawDirection]}方第${drawInfo.drawPile}墩（索引${startIndex}）开始，剩余${this.gameState.deck.length}张`);
   679→            }
   680→        }
   681→
   682→        // 初始化牌墙状态：每个方位17墩
   683→        this.gameState.wallState = { 1: 17, 2: 17, 3: 17, 4: 17 };
   684→
   685→        // 逆时针发牌顺序：东(1)→北(2)→西(3)→南(4)
   686→        // playerIds 是 [座位1, 座位2, 座位3, 座位4]
   687→        // 逆时针顺序就是 [座位1, 座位2, 座位3, 座位4]
   688→        const counterClockwiseIds = [
   689→            playerIds[0], // 座位1(东-庄家)
   690→            playerIds[1], // 座位2(北)
   691→            playerIds[2], // 座位3(西)
   692→            playerIds[3]  // 座位4(南)
   693→        ];
   694→
   695→        // 发牌：每人4张×3轮，然后每人1张，庄家多1张
   696→        // 每人4张×3轮（逆时针顺序）- 相当于每人2墩×3轮
   697→        for (let round = 0; round < 3; round++) {
   698→            for (const pid of counterClockwiseIds) {
   699→                for (let i = 0; i < 4; i++) {
   700→                    const card = this.gameState.deck.pop();
   701→                    if (card) this.gameState.hands[pid].push(card);
   702→                }
   703→            }
   704→        }
   705→
   706→        // 每人1张（逆时针顺序）
   707→        for (const pid of counterClockwiseIds) {
   708→            const card = this.gameState.deck.pop();
   709→            if (card) this.gameState.hands[pid].push(card);
   710→        }
   711→
   712→        // 庄家多拿1张
   713→        const dealerPid = playerIds[this.gameState.dealer];
   714→        const extraCard = this.gameState.deck.pop();
   715→        if (extraCard) this.gameState.hands[dealerPid].push(extraCard);
   716→
   717→        // 更新牌墙状态（根据实际抓取的牌数）
   718→        this.updateWallState();
   719→
   720→        // 庄家先出牌
   721→        this.gameState.currentPlayer = this.gameState.dealer;
   722→
   723→        // 排序手牌
   724→        for (const pid of playerIds) {
   725→            this.sortHand(pid);
   726→        }
   727→
   728→        console.log(`牌桌${this.tableNumber} 第${this.currentRound}局开始，庄家座位: ${this.gameState.dealerSeat}，万能牌: ${cardName(this.gameState.wildCard)}`);
   729→        console.log(`发牌完成，牌堆剩余: ${this.gameState.deck.length}张，牌墙状态: ${JSON.stringify(this.gameState.wallState)}`);
   730→
   731→        // 直接发送游戏状态（删除发牌动画）
   732→        this.broadcastGameState();
