   870→    // 排序手牌
   871→    sortHand(playerId) {
   872→        const hand = this.gameState.hands[playerId];
   873→        if (!hand) return;
   874→
   875→        const suitOrder = { '筒': 0, '条': 1, '万': 2, '风': 3, '箭': 4 };
   876→        const windOrder = { '东': 0, '南': 1, '西': 2, '北': 3 };
   877→        const arrowOrder = { '中': 0, '发': 1, '白': 2 };
   878→
   879→        hand.sort((a, b) => {
   880→            // 万能牌放最后
   881→            if (this.isWildCard(a) && !this.isWildCard(b)) return 1;
   882→            if (!this.isWildCard(a) && this.isWildCard(b)) return -1;
   883→
   884→            const suitA = suitOrder[a.suit] ?? 5;
   885→            const suitB = suitOrder[b.suit] ?? 5;
   886→            if (suitA !== suitB) return suitA - suitB;
   887→
   888→            if (a.type === 'number' && b.type === 'number') {
   889→                return a.rank - b.rank;
   890→            } else if (a.type === 'wind' && b.type === 'wind') {
   891→                return (windOrder[a.rank] ?? 0) - (windOrder[b.rank] ?? 0);
   892→            } else if (a.type === 'arrow' && b.type === 'arrow') {
   893→                return (arrowOrder[a.rank] ?? 0) - (arrowOrder[b.rank] ?? 0);
   894→            }
   895→            return 0;
   896→        });
   897→    }
