   899→    // 判断是否是万能牌（相同牌或红中）
   900→    isWildCard(card) {
   901→        const wild = this.gameState.wildCard;
   902→        if (!wild) return false;
   903→
   904→        // 相同牌是万能牌
   905→        if (card.suit === wild.suit && card.rank === wild.rank) return true;
   906→        // 红中也是万能牌
   907→        if (card.type === 'arrow' && card.rank === '中') return true;
   908→
   909→        return false;
   910→    }
