   930→    // 更新牌墙状态
   931→    updateWallState() {
   932→        // 计算已抓取的牌数（初始136张，减去亮牌1张，减去牌堆剩余）
   933→        const initialCards = 136 - 1; // 总牌数减去亮牌
   934→        const remainingCards = this.gameState.deck.length;
   935→        const drawnCards = initialCards - remainingCards;
   936→
   937→        // 牌墙初始状态：每个方位17墩，都从序号1开始
   938→        const wallState = {
   939→            1: { start: 1, count: 17 },  // 南
   940→            2: { start: 1, count: 17 },  // 西
   941→            3: { start: 1, count: 17 },  // 北
   942→            4: { start: 1, count: 17 }   // 东
   943→        };
   944→
   945→        // 根据 drawInfo 确定抓牌起始位置
   946→        const drawInfo = this.gameState.drawInfo;
   947→        if (!drawInfo || !drawInfo.drawDirection) {
   948→            this.gameState.wallState = wallState;
   949→            return;
   950→        }
   951→
   952→        // 座位映射：1=东, 2=北, 3=西, 4=南
   953→        // 牌墙方向（逆时针沿牌桌）：东(1) → 南(4) → 西(3) → 北(2) → 东
   954→        const directionOrder = [1, 2, 3, 4];
   955→        const seatToDirection = { 1: '东', 2: '南', 3: '西', 4: '北' };
   956→
   957→        // 抓牌方向：从序号1往17方向
   958→
   959→        const drawDir = drawInfo.drawDirection;
   960→        const drawIdx = directionOrder.indexOf(drawDir);
   961→        const startPile = drawInfo.drawPile; // 抓牌起始墩序号（1-17）
   962→
   963→        // 计算已抓取的牌墩数（每墩2张）
   964→        const drawnPiles = Math.floor(drawnCards / 2);
   965→
   966→        console.log(`更新牌墙: 已抓${drawnCards}张=${drawnPiles}墩, 抓牌起始${seatToDirection[drawDir]}第${startPile}墩`);
   967→
   968→        // 从抓牌起始位置开始，连续抓 drawnPiles 墩
   969→        // 计算每个方位保留的牌墩
   970→
   971→        let remainingToDraw = drawnPiles;
   972→        let currentDirIdx = drawIdx;
   973→
   974→        // 首先处理抓牌方位
   975→        // 从 startPile 开始到 17，共 (17 - startPile + 1) 墩可抓
   976→        let availableInDrawDir = 17 - startPile + 1;
   977→
   978→        if (remainingToDraw >= availableInDrawDir) {
   979→            // 抓牌方位的可抓部分全部被抓
   980→            // 保留序号 1 到 (startPile - 1)
   981→            wallState[drawDir] = { start: 1, count: startPile - 1 };
   982→            remainingToDraw -= availableInDrawDir;
   983→            // 逆时针移动
   984→            currentDirIdx = (currentDirIdx + 1) % 4;
   985→        } else {
   986→            // 只抓了一部分
   987→            // 保留序号 1 到 (startPile - 1) 和 (startPile + remainingToDraw) 到 17
   988→            const lastDrawn = startPile + remainingToDraw - 1;
   989→            if (startPile > 1) {
   990→                // 前面有保留
   991→                if (lastDrawn < 17) {
   992→                    // 后面也有保留
   993→                    wallState[drawDir] = {
   994→                        start: 1,
   995→                        count: startPile - 1,
   996→                        endKeep: { start: lastDrawn + 1, count: 17 - lastDrawn }
   997→                    };
   998→                } else {
   999→                    // 后面没有保留
  1000→                    wallState[drawDir] = { start: 1, count: startPile - 1 };
  1001→                }
  1002→            } else {
  1003→                // 前面没有保留
  1004→                if (lastDrawn < 17) {
  1005→                    wallState[drawDir] = { start: lastDrawn + 1, count: 17 - lastDrawn };
  1006→                } else {
  1007→                    wallState[drawDir] = { start: 0, count: 0 };
  1008→                }
  1009→            }
  1010→            remainingToDraw = 0;
  1011→        }
  1012→
  1013→        // 逆时针处理其他方位
  1014→        while (remainingToDraw > 0 && currentDirIdx !== drawIdx) {
  1015→            const currentDir = directionOrder[currentDirIdx];
  1016→
  1017→            if (remainingToDraw >= 17) {
  1018→                // 这个方位全部被抓
  1019→                wallState[currentDir] = { start: 0, count: 0 };
  1020→                remainingToDraw -= 17;
  1021→            } else {
  1022→                // 只抓了一部分，从序号1开始抓 remainingToDraw 墩
  1023→                // 保留序号 (remainingToDraw + 1) 到 17
  1024→                wallState[currentDir] = { start: remainingToDraw + 1, count: 17 - remainingToDraw };
  1025→                remainingToDraw = 0;
  1026→            }
  1027→            // 逆时针移动
  1028→            currentDirIdx = (currentDirIdx + 1) % 4;
  1029→        }
  1030→
  1031→        this.gameState.wallState = wallState;
  1032→        console.log(`牌墙状态更新: ${JSON.stringify(wallState)}`);
  1033→    }
