  1094→        // 找所有相同的牌（不包括万能牌替代）
  1095→        const sameCards = hand.filter(c =>
  1096→            c.suit === targetCard.suit && c.rank === targetCard.rank
  1097→        );
  1098→
  1099→        if (sameCards.length !== 4) return false;
  1100→
  1101→        // 移除这4张牌
