  1103→            !(c.suit === targetCard.suit && c.rank === targetCard.rank)
  1104→        );
  1105→
  1106→        // 加入展示区
  1107→        this.gameState.showedCards[playerId].gang.push(sameCards);
  1108→
  1109→        return sameCards;
  1110→    }
