  1624→// 广播牌桌列表给所有已登录客户端
  1625→function broadcastTableList() {
  1626→    const tableList = Array.from(tables.values()).map(t => t.getTableInfo());
  1627→    const message = JSON.stringify({
  1628→        type: 'tableList',
