  1641→}
  1642→
  1643→// 创建牌桌
  1644→function createTable() {
  1645→    tableCounter++;
  1646→    const tableId = `table_${tableCounter}`;
  1647→    const table = new GameTable(tableId, tableCounter);
  1648→    tables.set(tableId, table);
  1649→    console.log(`创建新牌桌: ${tableId}`);
  1650→    return table;
  1651→}
  1652→
  1653→// 加入牌桌
  1654→function joinTable(ws, playerId, playerName, tableId, seatNum) {
  1655→    const table = tables.get(tableId);
  1656→    if (!table) {
  1657→        ws.send(JSON.stringify({ type: 'error', message: '牌桌不存在' }));
  1658→        return false;
