    if (stopPileNum === (stopStep === 1 ? 17 : 1)) {
        // 停在方位的最后一墩，下一墩是下一个方位的第一墩
        const nextDirIdx = (currentDirIdx + 1) % 4;
        drawDirection = directionOrder[nextDirIdx];
        drawPile = startPileNum[drawDirection];
    } else {
        drawDirection = stopDirection;
        drawPile = stopPileNum + stopStep;
    }

    console.log(`抓牌起始: ${seatToDirection[drawDirection]}方第${drawPile}墩`);

    // 确定亮牌位置
    // 抓牌方位的逆时针下一个方位，从序号17往1数 firstSum 墩
    const drawDirIdx = directionOrder.indexOf(drawDirection);
    const shownDirIdx = (drawDirIdx + 1) % 4; // 逆时针下一个
    const shownDirection = directionOrder[shownDirIdx];

    // 亮牌方向：从序号17往1数
    const shownPile = 17 - (firstSum - 1); // 从17开始，数firstSum墩后的位置

    console.log(`亮牌位置: ${seatToDirection[shownDirection]}方第${shownPile}墩（从序号17开始往1数${firstSum}墩）`);

