console.log(`第1次骰子: ${firstSum}, 第2次骰子: ${secondSum}, 总计: ${total}`);

// 座位映射：1=东, 2=南, 3=西, 4=北
const seatToDirection = { 1: '东', 2: '南', 3: '西', 4: '北' };
// 牌墙方向（逆时针沿牌桌）：东(1) → 南(2) → 西(3) → 北(4) → 东
const directionOrder = [1, 2, 3, 4];

// 第1次掷骰者的座位
const firstRollerSeat = this.players.get(this.diceState.firstRoll.playerId)?.seatNum || 1;

// 第1次骰子点数决定第2次掷骰者：从庄家（第1次掷骰者）开始逆时针数 firstSum 个玩家
const firstRollerIdx = directionOrder.indexOf(firstRollerSeat);
const secondRollerIdx = (firstRollerIdx + firstSum - 1) % 4;
const secondRollerSeat = directionOrder[secondRollerIdx];

console.log(`第1次掷骰者: ${seatToDirection[firstRollerSeat]}(座位${firstRollerSeat}), 数${firstSum}个后是: ${seatToDirection[secondRollerSeat]}(座位${secondRollerSeat})`);

// ========== 正确规则 ==========
// 1. 抓牌起点：从第2次掷骰者开始数 total 墩
// 2. 亮牌位置：在抓牌起始点的**上一家**牌墙上，从17往1数 firstSum 下

// 从第2次掷骰者开始数 total 墩，找到抓牌起始点
let remainingPiles = total;
let currentDirIdx = directionOrder.indexOf(secondRollerSeat);
let drawPile = 1;

while (remainingPiles > 0) {
    if (remainingPiles > 17) {
        remainingPiles -= 17;
        currentDirIdx = (currentDirIdx + 1) % 4;
    } else {
        drawPile = remainingPiles;
        remainingPiles = 0;
    }
}

const drawDirection = directionOrder[currentDirIdx];
console.log(`数${total}墩后，抓牌起始: ${seatToDirection[drawDirection]}方第${drawPile}墩`);

// 亮牌在抓牌起始点的上一家（逆时针方向前一个方位）
const shownDirIdx = (currentDirIdx + 3) % 4; // 逆时针前一个 = 索引-1 = +3 mod 4
const shownDirection = directionOrder[shownDirIdx];
const shownPile = 17 - firstSum + 1; // 从17往1数firstSum下

console.log(`亮牌位置: ${seatToDirection[shownDirection]}方第${shownPile}墩（抓牌上一家，从17往1数${firstSum}下）`);

// 计算牌堆中的实际索引
// 牌墙按 [东17墩][南17墩][西17墩][北17墩] 排列（逆时针沿牌桌）
const directionToOffset = { 1: 0, 2: 17, 3: 34, 4: 51 };
// 序号转索引：序号1对应索引0，序号17对应索引16

